from typing import List


class Solution:
    def findMaxAverage(self, nums: List[int], k: int) -> float:
        avg = -float("inf")
        total = 0
        # [1,12,-5,-6,50,3] - values
        # [0, 1, 2, 3, 4,5] - index
        for i in range(len(nums) - k + 1):
            total = 0
            for j in range(i, k + i):
                total += nums[j]
                print("men total man", total, j)
            print("men to'liq totalman", total)
            avg = max((total / k), avg)
            print(avg)
        return avg
    
